style.css:
@-moz-document domain("youtube.com") {
/* 1. Fondo principal de la página */
    html, body, #page-manager, ytd-app {
        background: url("https://i.postimg.cc/qvFyg7p4/PIC1.png") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* 2. Transparencias globales */
    ytd-page-manager, ytd-browse, ytd-watch-flexy, #columns, #primary, #secondary, 
    #contentContainer, ytd-popup-container, #page-manager.ytd-app, 
    ytd-two-column-browse-results-renderer, ytd-rich-grid-renderer, 
    #primary.ytd-two-column-browse-results-renderer, ytd-guide-content-renderer, 
    #guide-inner-content.ytd-guide-renderer, #guide-content.ytd-app, ytd-guide-renderer {        
        background: transparent !important;
        background-color: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }

    /* 3. Barra superior fija */
    #masthead-container.ytd-app, #masthead-container.ytd-app[sticky], ytd-masthead, #background.ytd-masthead { 
        background: rgba(110, 110, 110, 0.65) !important; 
        background-color: rgba(110, 110, 110, 0.65) !important;
        backdrop-filter: blur(4px) !important; 
        border-bottom: 1px solid rgba(255, 255, 255, 0.15) !important;
    }

    /* 4. Estilo de las "cápsulas" */
    ytd-watch-metadata, #above-the-fold #description, ytd-comments #sections, 
    ytd-compact-video-renderer, .ytd-watch-next-secondary-results-renderer, 
    ytd-playlist-panel-renderer, #container.ytd-playlist-panel-renderer, 
    ytd-rich-grid-media, ytd-rich-item-renderer, #guide-wrapper {                                
        background: rgba(110, 110, 110, 0.65) !important; 
        background-color: rgba(110, 110, 110, 0.65) !important;
        backdrop-filter: blur(4px) !important;
        border-radius: 16px !important; 
        border: 1px solid rgba(255, 255, 255, 0.15) !important;
    }

    /* 5. MENÚ LATERAL ESTRECHO Y POSICIONADO */
    #guide-wrapper {
        width: 180px !important; 
        margin-left: -10px !important; 
        padding: 10px !important;
        margin-top: 20px !important;
        height: calc(100vh - 120px) !important;
        position: fixed !important;
        z-index: 2000 !important;
    }

    /* 6. RESTAURACIÓN DE CATEGORÍAS */
    #chips-wrapper.ytd-feed-filter-chip-bar-renderer {
        display: block !important;
        background: transparent !important;
        margin-bottom: 20px !important;
    }

    yt-chip-cloud-chip-renderer {
        background: rgba(110, 110, 110, 0.4) !important;
        backdrop-filter: blur(4px) !important;
        border-radius: 12px !important; 
        border: 1px solid rgba(255, 255, 255, 0.15) !important;
        color: #ffffff !important;
        margin-right: 10px !important;
    }

    yt-chip-cloud-chip-renderer[selected] {
        background: rgba(255, 255, 255, 0.85) !important;
        color: #000000 !important;
    }

    yt-chip-cloud-chip-renderer yt-formatted-string {
        color: inherit !important;
    }

    /* 7. Eliminación de bordes sobrantes */
    .yt-spec-divider, #sections.ytd-guide-renderer > ytd-guide-section-renderer:not(:first-child),
    #masthead-container::after, #header.ytd-rich-grid-renderer, ytd-feed-filter-chip-bar-renderer {            
        border: none !important;
        box-shadow: none !important;
    }

    /* 8. Legibilidad de textos (Títulos) */
    #video-title, #video-title-link, yt-formatted-string, .title.ytd-guide-entry-renderer {             
        color: #ffffff !important;
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.7) !important;
    }

    /* 8.1. MODO OSCURO — Variables y textos secundarios forzados a blanco */
    html[dark] {
        --yt-spec-text-secondary: #ffffff !important;
        --yt-spec-text-primary: #ffffff !important;
        --yt-spec-text-primary-inverse: #ffffff !important;
        --ytd-video-meta-color: #ffffff !important;
        --yt-secondary-text-color: #ffffff !important;
        --yt-spec-icon-inactive: rgba(255,255,255,0.7) !important;
        --yt-spec-text-disabled: rgba(255,255,255,0.6) !important;
        --ytd-channel-name-link-color: #ffffff !important;
    }

    html[dark] ytd-rich-grid-media #metadata-line span,
    html[dark] ytd-rich-grid-media #metadata-line yt-formatted-string,
    html[dark] ytd-rich-grid-media #metadata *,
    html[dark] ytd-rich-grid-media ytd-video-meta-block *,
    html[dark] ytd-rich-grid-media #channel-name *,
    html[dark] ytd-rich-grid-media #byline-text *,
    html[dark] ytd-rich-grid-media .inline-metadata-item,
    html[dark] ytd-rich-item-renderer #metadata-line span,
    html[dark] ytd-rich-item-renderer #metadata *,
    html[dark] ytd-rich-item-renderer ytd-video-meta-block *,
    html[dark] ytd-rich-item-renderer #channel-name *,
    html[dark] ytd-rich-item-renderer .inline-metadata-item,
    html[dark] ytd-compact-video-renderer #metadata-line span,
    html[dark] ytd-compact-video-renderer #channel-name *,
    html[dark] ytd-compact-video-renderer .inline-metadata-item,
    html[dark] ytd-compact-video-renderer ytd-video-meta-block * {
        color: #ffffff !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.85) !important;
        opacity: 1 !important;
    }

    /* 8.2. FIX TEXTOS METADATOS — clase hardcodeada de YouTube (View Model) */
    .ytAttributedStringWhiteSpacePreWrap,
    .ytAttributedStringHost,
    .ytContentMetadataViewModelMetadataText,
    .ytAttributedStringLinkInheritColor {
        color: #ffffff !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.85) !important;
        opacity: 1 !important;
    }

    /* 9. Barra lateral reproductor — transparencia reducida */
    #secondary.ytd-watch-flexy,
    #secondary-inner.ytd-watch-flexy,
    ytd-watch-next-secondary-results-renderer,
    #items.ytd-watch-next-secondary-results-renderer {
        background: transparent !important;
        background-color: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }

    ytd-compact-video-renderer,
    ytd-compact-playlist-renderer,
    ytd-compact-radio-renderer {
        background: rgba(110, 110, 110, 0.25) !important;
        background-color: rgba(110, 110, 110, 0.25) !important;
        backdrop-filter: blur(4px) !important;
        border-radius: 12px !important;
        border: 1px solid rgba(255, 255, 255, 0.10) !important;
        margin-bottom: 6px !important;
    }

    /* 10. Ocultar el modo ambiente */
    .ytd-watch-flexy[cinematic-theme] #cinematic.ytd-watch-flexy, #cinematic-container, #cinematic {
        display: none !important;
    }
}
